import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Git相关命令","description":"","frontmatter":{"title":"Git相关命令","author":"麻瓜【码瓜】","date":"2024-07-01"},"headers":[],"relativePath":"posts/aboutgitcmd.md","filePath":"posts/aboutgitcmd.md","lastUpdated":1794548361000}'),p={name:"posts/aboutgitcmd.md"};function n(l,a,o,c,d,h){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="git相关命令" tabindex="-1">Git相关命令 <a class="header-anchor" href="#git相关命令" aria-label="Permalink to &quot;Git相关命令&quot;">​</a></h1><h2 id="git配置信息" tabindex="-1">Git配置信息 <a class="header-anchor" href="#git配置信息" aria-label="Permalink to &quot;Git配置信息&quot;">​</a></h2><p>查看Git配置信息</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --list</span></span></code></pre></div><h2 id="git账号设置" tabindex="-1">Git账号设置 <a class="header-anchor" href="#git账号设置" aria-label="Permalink to &quot;Git账号设置&quot;">​</a></h2><p>账号全局设置(针对系统当前用户进行设置)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global user.name &quot;USERNAME&quot;</span></span></code></pre></div><p>邮箱全局设置(针对系统当前用户进行设置)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global user.email &quot;EMAIL&quot;</span></span></code></pre></div><p>查看账号、邮箱</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global user.name</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global user.email</span></span></code></pre></div><p>如果只正对当前项目进行设置，则不需要带参数--global，例子如下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config user.name &quot;USERNAME&quot;</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config user.email &quot;EMAIL&quot;</span></span></code></pre></div><h2 id="github账号" tabindex="-1">GitHub账号 <a class="header-anchor" href="#github账号" aria-label="Permalink to &quot;GitHub账号&quot;">​</a></h2><p>查看本地登录的Github账号</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git credential-manager github list</span></span></code></pre></div><p>登录GitHub账号</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git credential-manager github login --username &lt;username&gt;</span></span></code></pre></div><p>执行命令后会弹出窗口要求输入密码登录<br> 退出GitHub账号</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git credential-manager github logout &lt;account&gt;</span></span></code></pre></div><h2 id="仓库" tabindex="-1">仓库 <a class="header-anchor" href="#仓库" aria-label="Permalink to &quot;仓库&quot;">​</a></h2><p>新建并初始化仓库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git init &lt;dir&gt;</span></span></code></pre></div><p>现有目录初始化</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git init</span></span></code></pre></div><p>产生新的分支并切换到新的分支</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout -b NewBranch</span></span></code></pre></div><p>不带参数<code>-b</code>则是切换<br> 添加文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git add .</span></span></code></pre></div><p>添加备注</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git commit -m &#39;deploy&#39;</span></span></code></pre></div><p>推送到远程仓库（main分支）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push -f git@github.com:melonpeasant/melonpeasant.github.io.git main</span></span></code></pre></div><hr><p>将本地分支和远程分支关联</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote add origin git@github.com:&lt;username&gt;/&lt;repo&gt;.git</span></span></code></pre></div><p>使用上面的命令后，可以直接使用下面的命令进行推送、删除、重命名<br> 推送到远程仓库（main分支）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push -u origin main</span></span></code></pre></div><p>删除远程仓库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote rm &lt;repo&gt;</span></span></code></pre></div><p>重新命名仓库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote rename &lt;old.repo&gt; &lt;new.repo&gt;</span></span></code></pre></div><hr><h2 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to &quot;分支&quot;">​</a></h2><p>列出本地分支</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch</span></span></code></pre></div><p>列出远程分支</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch -r</span></span></code></pre></div><p>列出所有分支（本地+远程）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch -a</span></span></code></pre></div><p>删除本地分支</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch -d &lt;branch&gt;</span></span></code></pre></div><p>如果你还在一个分支上，那么 Git 是不允许你删除这个分支的。所以，请记得退出分支</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout &lt;branch&gt;</span></span></code></pre></div><p>参数<code>-d</code>是删除(<code>--delete</code>)<br> 参数<code>-D</code>是强行删除(<code>--delete --force</code>) 删除远程分支</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push origin --delete --force remoteBranchName</span></span></code></pre></div><p>添加<code>--force</code>会强行删除</p>',59)])])}const b=s(p,[["render",n]]);export{u as __pageData,b as default};
